from dataclasses import dataclass
from adaptix import Retort, name_mapping, NameStyle, DebugTrail
from adaptix.load_error import ExtraFieldsLoadError
from adaptix.struct_trail import get_trail
@dataclass
class Model:
    first_name: int
    other: int = 3
for debug in DebugTrail:
    r = Retort(recipe=[name_mapping(Model, aliases={'first_name': ('old', 'older')}, alias_style=NameStyle.CAMEL)], debug_trail=debug)
    assert r.load({'old': 1}, Model) == Model(1)
    assert r.load({'firstName': 2}, Model) == Model(2)
    try: r.load({'old': 1, 'older': 2}, Model)
    except Exception as e: print(debug, type(e).__name__)
    else: raise AssertionError('missing conflict')
    try: r.load({'old': 'bad'}, Model)
    except Exception as e: print('trail', debug, list(get_trail(e)), str(e))
print('checks complete')
